const paths={eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm7 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0',plus:'M12 5v14M5 12h14',minus:'M5 12h14',down:'m7 10 5 5 5-5',right:'m9 6 6 6-6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',folder:'M3 6h6l3 3h9v11H3Z',folderPick:'M3 6h6l3 3h9v11H3ZM12 12v5m-2.5-2.5h5',folderOpen:'M3 7h6l3 3h8M3 7v13h17l2-10M15 3h6v6m0-6-7 7',calendar:'M5 5h14v16H5ZM8 3v4m8-4v4M5 10h14m-10 5h6',clock:'M12 7v6l4 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-6 0v6',inbox:'m5 4-3 11v5h20v-5L19 4ZM2 15h6l2 3h4l2-3h6M8 8h8',list:'M9 6h12M9 12h12M9 18h12M3 6h1m-1 6h1m-1 6h1',user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0M5 21v-3a7 7 0 0 1 14 0v3',refresh:'M20 5v6h-6M4 19v-6h6M5 8a8 8 0 0 1 13-4l2 3M4 17l2 3a8 8 0 0 0 13-4',edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',trash:'M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6m4-6v6',star:'m12 3 2.8 6 6.5.8-4.7 4.5 1.1 6.5L12 17.7l-5.7 3.1 1.1-6.5L2.7 9.8 6.5 9Z',arrow:'M4 12h16m-6-6 6 6-6 6',link:'m9 15 6-6M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.settings}"/></svg>`;
const btn=(text,act,variant='secondary',attrs='')=>`<button class="btn ${variant}" data-act="${act}" ${attrs}>${text}</button>`;
const ib=(name,title,act,attrs='')=>`<button class="icon-btn" aria-label="${title}" title="${title}" data-act="${act}" ${attrs}>${icon(name)}</button>`;
const roles=[{id:'organizer',name:'事项整理',desc:'理解原文，整理有依据的事项。',icon:'inbox',focus:[['balanced','执行与跟进兼顾'],['my_actions','更关注本人执行'],['followups','更关注本人跟进']]},{id:'tracker',name:'进展跟踪',desc:'把后续线索接到已有事项。',icon:'link',focus:[['evidence','优先呈现原文依据'],['risks','优先呈现风险与变化']]},{id:'advisor',name:'工作参谋',desc:'基于已确认的事实理清重点。',icon:'calendar',focus:[['deadline','优先关注交付截止'],['followup','优先关注跟进安排']]}];
const seed={profile:{name:'小明同学',address:'BOSS'},general:{root:'/Users/demo/Documents/Sidekick',zone:'Asia/Shanghai'},providers:[{id:'team',name:'公司模型网关',url:'https://gateway.example.com/v1',enabled:true,keyStored:true,authMode:'key',env:'',timeout:60,retries:2,headerName:'',headerValue:''},{id:'personal',name:'个人模型服务',url:'https://model.example.com/v1',enabled:true,keyStored:true,authMode:'key',env:'',timeout:60,retries:1,headerName:'',headerValue:''}],models:[{id:'team-main',provider:'team',name:'团队主力',apiModelId:'team-chat',contextWindow:64000,maxTokens:4096,toolCall:true,reasoning:false,effort:'default',temperature:'',topP:'',description:'日常资料整理与工作建议',aliases:'',priceInput:'',priceOutput:'',priceCache:'',currency:'CNY',enabled:true},{id:'team-fast',provider:'team',name:'轻量快模',apiModelId:'team-chat-fast',contextWindow:32000,maxTokens:4096,toolCall:true,reasoning:false,effort:'default',temperature:'',topP:'',description:'轻量文本整理',aliases:'',priceInput:'',priceOutput:'',priceCache:'',currency:'CNY',enabled:true},{id:'personal-reason',provider:'personal',name:'个人推理模型',apiModelId:'personal-reasoner',contextWindow:64000,maxTokens:4096,toolCall:true,reasoning:true,effort:'medium',temperature:'',topP:'',description:'合成演示模型，参数不是实测规格',aliases:'',priceInput:'',priceOutput:'',priceCache:'',currency:'CNY',enabled:true}],defaultModel:'team-main',roles:{organizer:{modelId:'',focus:'balanced',detail:'concise',instructions:'先写清由谁负责，保留可以核对的原文。'},tracker:{modelId:'team-fast',focus:'evidence',detail:'standard',instructions:''},advisor:{modelId:'',focus:'deadline',detail:'concise',instructions:''}}};
const state={saved:clone(seed),draft:{profile:clone(seed.profile),general:clone(seed.general),providers:{},models:{},roles:clone(seed.roles)},route:['general','models','agents','profile','inbox','components','about'].includes(location.hash.slice(1))?location.hash.slice(1):'general',provider:'team',model:null,modelView:false,role:'organizer',scene:'normal',sample:'我负责整理模型网关接入清单，周五17点前提交。\n林川负责修复SDK鉴权，我今天15点跟进，周五17点前交付。\n我确认试用名单，时间待定。',trialTab:'sample',trialStatus:'idle',trialSnapshot:null,trialCandidates:[],status:{},error:'',pendingRoot:'',sourceTime:'2026-10-29 12:30',batch:'review',captureText:'',serial:0,candidates:[{id:'c1',title:'整理模型网关接入清单',kind:'action',owner:'我',due:'2026-10-30 17:00',followup:'',evidence:'我负责整理模型网关接入清单，周五17点前提交。',status:'pending',selected:true},{id:'c2',title:'跟进林川修复 SDK 鉴权问题',kind:'followup',owner:'林川',due:'2026-10-30 17:00',followup:'2026-10-29 15:00',evidence:'林川负责修复SDK鉴权，我今天15点跟进，周五17点前交付。',status:'pending',selected:true},{id:'c3',title:'确认试用名单',kind:'action',owner:'我',due:'',followup:'',evidence:'我确认试用名单，时间待定。',status:'accepted',selected:false}],editingCandidate:null,labDate:'2026-10-30 17:00',labDateOnly:'2026-10-31',labNumber:2,labSwitch:true,labChecked:true,pendingDefault:null};
let menus={},activeMenu=null,dateState=null,toastTimer=null,trialTimer=null;
const keyDrafts={};
const usableModel=id=>{const m=findModel(id);return !!(m?.enabled&&findProvider(m.provider)?.enabled);};
const findProvider=id=>state.saved.providers.find(p=>p.id===id);
const findModel=id=>state.saved.models.find(m=>m.id===id);
function providerDraft(id=state.provider){return state.draft.providers[id]??=(clone(findProvider(id)||{id,name:'',url:'',enabled:true,keyStored:false,authMode:'key',env:'',timeout:60,retries:2,headerName:'',headerValue:''}));}
function modelDraft(id=state.model){return state.draft.models[id]??=clone(findModel(id)||{...seed.models[0],id,provider:state.provider,name:'',apiModelId:'',description:'',reasoning:false,aliases:'',priceInput:'',priceOutput:'',priceCache:''});}
function resolvedRole(id){return state.saved.roles[id].modelId||state.saved.defaultModel;}
function refs(id){const result=[];if(state.saved.defaultModel===id)result.push('全局默认');for(const r of roles)if(resolvedRole(r.id)===id)result.push(r.name);return result;}
const enabledModels=()=>state.saved.models.filter(m=>m.enabled&&findProvider(m.provider)?.enabled);
function modelOptions(inherit=false){const out=[];if(inherit)out.push({value:'',label:`继承全局默认 · ${findModel(state.saved.defaultModel)?.name||'尚未设置'}`,group:'跟随全局'});for(const p of state.saved.providers){for(const m of enabledModels().filter(m=>m.provider===p.id))out.push({value:m.id,label:m.name,description:m.apiModelId,group:p.name});}return out;}
function selectControl(name,value,options,placeholder='请选择',search=false){const items=options.map(o=>Array.isArray(o)?{value:o[0],label:o[1]}:o);menus[name]={items,value,search};const selected=items.find(o=>String(o.value)===String(value));return `<button class="control-select" type="button" role="combobox" aria-expanded="false" aria-haspopup="listbox" ${!selected&&value!==''?'aria-invalid="true"':''} aria-controls="select-options" data-select="${name}" id="control-${name}"><span class="selection">${e(selected?.label||(value!==''&&value!==null?'已选项目不可用':placeholder||'请选择'))}</span>${icon('down')}</button>`;}
let fieldSerial=0;
function field(label,control,help='',full=false){
 const match=control.match(/<(?:input|textarea|button)\b[^>]*?\bid="([^"]+)"/),id=match?match[1]:`field-${++fieldSerial}`;
 if(!match)control=control.replace(/<(input|textarea|button)\b/,`<$1 id="${id}"`);
 return `<div class="field ${full?'full':''}"><div class="field-label-row">${/<(input|textarea|button)\b/.test(control)?`<label for="${id}">${label}</label>`:`<span>${label}</span>`}</div>${control}${help?`<small>${help}</small>`:''}</div>`;
}
function input(bind,value,placeholder='',attrs=''){return `<input class="input" data-bind="${bind}" value="${e(value)}" placeholder="${e(placeholder)}" ${attrs}>`;}
function num(bind,value,min,max,step=1){return `<div class="number-control"><button type="button" class="icon-btn" data-step="${bind}" data-delta="-${step}" aria-label="减少数值">${icon('minus')}</button><input id="number-${bind}" type="text" role="spinbutton" inputmode="decimal" aria-valuemin="${min}" aria-valuemax="${max}" aria-valuenow="${e(value)}" data-bind="${bind}" data-min="${min}" data-max="${max}" value="${e(value)}"><button type="button" class="icon-btn" data-step="${bind}" data-delta="${step}" aria-label="增加数值">${icon('plus')}</button></div>`;}
function dateControl(name,value,only=false){return `<button type="button" class="control-select date-control" id="date-${name}" data-date="${name}" data-date-only="${only}" aria-haspopup="dialog" aria-expanded="false"><span class="selection ${value?'':'muted'}">${e(value||'选择日期'+(only?'':'与时间'))}</span>${icon(only?'calendar':'clock')}</button>`;}
function context(){if(state.route==='general')return {key:'general',draft:state.draft.general,saved:state.saved.general,label:'保存设置'};if(state.route==='profile')return {key:'profile',draft:state.draft.profile,saved:state.saved.profile,label:'保存个人信息'};if(state.route==='agents')return {key:`role-${state.role}`,draft:state.draft.roles[state.role],saved:state.saved.roles[state.role],label:'保存偏好'};if(state.route==='models')return state.modelView?{key:`model-${state.model}`,draft:modelDraft(),saved:findModel(state.model),label:'保存模型'}:{key:`provider-${state.provider}`,draft:providerDraft(),saved:findProvider(state.provider),label:'保存服务'};return null;}
function dirty(){const c=context();return c?JSON.stringify(c.draft)!==JSON.stringify(c.saved):false;}
function statusText(){const c=context();return c&&state.status[c.key];}
function savebar(){if(state.route==='inbox'){const pending=state.candidates.filter(c=>c.status==='pending'),selected=pending.filter(c=>c.selected);return `<span class="status-copy">${pending.length?`<button class="text" data-act="toggle-all">${selected.length===pending.length?'取消全选':'全选'}</button><span>已选 ${selected.length} / ${pending.length} 条</span>`:'这个批次已处理完'}</span><div class="row-actions">${btn(icon('check')+'签收选中事项','sign','commit',selected.length?'':'disabled')}</div>`;}if(!context())return `<span class="status-copy">${icon('info')}合成数据与交互演示，不读写生产配置。</span>`;const d=dirty(),error=state.error;return `<span class="status-copy ${d?'dirty':''} ${error?'error':''}" role="status">${icon(error?'info':d?'edit':'check')}<span>${e(error||(d?'有未保存的修改':statusText()||'没有未保存的修改'))}</span></span><div class="row-actions">${btn('放弃修改','discard','quiet',d?'':'disabled')}${btn(context().label,'save','commit',d?'':'disabled')}</div>`;}
function updateSavebar(){const bar=$('#savebar');bar.innerHTML=savebar();const trial=$('[data-act=start-trial]');if(trial)trial.disabled=dirty()||state.trialStatus==='running';const test=$('[data-act=test-provider]');if(test)test.disabled=dirty();}
function heading(){const map={general:['通用设置','安排工作目录与日期规则。'],profile:['个人信息','让班班认识你，也知道怎么称呼你。'],models:['模型服务','一个服务管理一组模型，供不同角色选择。'],agents:['智能体','三个固定分工，分别安排模型与工作习惯。'],about:['关于跟班','盯着呢，老板。']};const [title,desc]=map[state.route]||['公共表单组件','同一套尺寸、状态与交互，覆盖所有业务页面。'];return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${state.route==='models'?`<div class="global-model"><label class="field-label" for="control-global-model">全局默认模型</label><div class="default-model-row">${selectControl('global-model',state.pendingDefault||state.saved.defaultModel,modelOptions(),'',true)}${state.pendingDefault?btn('应用','apply-default','entry small'):''}</div></div>`:''}</div>`;}
function tabs(){return `<div class="settings-tabs" role="tablist" aria-label="设置分类">${[['profile','个人信息'],['general','通用'],['models','模型服务'],['agents','智能体'],['about','关于']].map(([id,name])=>`<button class="settings-tab ${state.route===id?'active':''}" role="tab" aria-selected="${state.route===id}" tabindex="${state.route===id?0:-1}" data-route="${id}">${name}</button>`).join('')}</div>`;}
function general(){return `<section class="section-row"><div class="section-label"><h2>工作目录</h2><p>配置、事项和运行资料的保存位置。</p></div><div class="section-body"><div class="field"><label for="work-root">当前保存位置</label><div class="input-group"><input id="work-root" value="${e(state.saved.general.root)}" readonly aria-label="当前保存位置" title="${e(state.saved.general.root)}">${ib('folderPick','选择新目录','choose-root')}${ib('folderOpen','打开目录','open-root')}</div></div><div class="directory-help"><small>完整路径可选中复制。</small><small>目录更换独立确认，保留原数据。</small></div>${state.pendingRoot?`<div class="root-migration"><strong>切换到：${e(state.pendingRoot)}</strong><p>先备份、迁移并校验，再切换保存位置。</p><div class="row-actions">${btn('迁移并切换（演示）','migrate-root','entry','')}${btn('取消','cancel-root','quiet')}</div></div>`:''}</div></section><section class="section-row"><div class="section-label"><h2>日期与时间</h2><p>统一所有页面的时间规则。</p></div><div class="section-body"><div class="field"><label for="control-zone">应用时区</label>${selectControl('zone',state.draft.general.zone,[{value:'Asia/Shanghai',label:'中国标准时间 · 上海',description:'UTC+08:00'},{value:'Asia/Tokyo',label:'日本标准时间 · 东京',description:'UTC+09:00'},{value:'Europe/London',label:'英国时间 · 伦敦',description:'随夏令时切换'},{value:'America/New_York',label:'美国东部时间 · 纽约',description:'随夏令时切换'}],'',true)}</div><p class="time-policy">用于日期理解、显示和日期归组。更改不会挪动已有事项的具体截止时刻；仅日期仍保留日期值。</p></div></section>`;}
function profile(){return `<section class="section-row"><div class="section-label"><h2>个人资料</h2><p>昵称与班班称呼独立设置。</p></div><div class="section-body"><div class="form-grid">${field('昵称',input('profile.name',state.draft.profile.name,'小明同学','maxlength="60"'))}${field('班班对我的称呼',input('profile.address',state.draft.profile.address,'BOSS','maxlength="60"'),'<button class="text" data-act="copy-name">与昵称一致</button>')}</div><div class="profile-preview"><img src="../brand/sidekick-mark.svg" alt="班班"><div><small>保存后，班班会这样招呼你</small><strong style="display:block">${e(state.draft.profile.address||'BOSS')}，随时交给我。</strong></div></div></div></section>`;}
function providerForm(){const p=providerDraft();return `<div class="object-heading"><div><h2>${e(findProvider(state.provider)?.name||'新增供应商')}</h2><p>OpenAI兼容接口 · ${state.saved.models.filter(m=>m.provider===p.id).length} 个模型</p></div><div class="row-actions"><label class="service-toggle"><input class="switch" type="checkbox" role="switch" aria-label="启用供应商" title="启用供应商" data-bind="provider.enabled" ${p.enabled?'checked':''}><span>启用</span></label><span class="tag ${state.status['test-'+p.id]==='failed'?'bad':''}">${state.status['test-'+p.id]==='passed'?'演示测试通过':state.status['test-'+p.id]==='failed'?'演示连接失败':'未测试'}</span>${btn(icon('refresh')+'测试连接','test-provider','secondary small',dirty()?'disabled':'')}${ib('trash','删除供应商','delete-provider')}</div></div><div class="service-form"><div class="form-grid">${field('显示名称',input('provider.name',p.name,'例如：公司模型网关','maxlength="100"'))}${field('接口协议','<div class="protocol-value">OpenAI兼容<span class="tag subtle">当前适配路径</span></div>')}${field('服务地址',input('provider.url',p.url,'https://gateway.example.com/v1','type="url"'),'',true)}${field('认证方式',selectControl('auth-mode',p.authMode,[['key','API Key · 钥匙串'],['env','环境变量引用']]))}${p.authMode==='env'?field('环境变量名称',input('provider.env',p.env,'例如：SIDEKICK_MODEL_KEY','autocomplete="off"')):field('API Key',`<div class="input-group"><input type="password" data-key-draft autocomplete="off" value="${e(keyDrafts[p.id]||'')}" placeholder="${p.keyStored?'已保存 · 留空保留原Key':'演示占位，请勿填写真实密钥'}" aria-label="API Key">${ib('eye','显示或隐藏演示Key','toggle-key')}</div>`)}</div><details class="advanced"><summary>连接选项${icon('down')}</summary><div class="form-grid">${field('单次请求超时（秒）',num('provider.timeout',p.timeout,1,120))}${field('失败重试次数',num('provider.retries',p.retries,0,2))}</div><p>重试和工具循环共同受任务总时限约束。</p><div class="header-param-row">${input('provider.headerName',p.headerName,'非秘密请求头名称','aria-label="非秘密请求头名称"')}${input('provider.headerValue',p.headerValue,'固定值；认证信息请用凭据引用','aria-label="非秘密请求头值"')}</div></details></div><section class="model-section"><div class="section-heading"><h3>模型<span>${state.saved.models.filter(m=>m.provider===p.id).length} 个</span></h3>${btn(icon('plus')+'新增模型','add-model','entry small',findProvider(p.id)?'':'disabled')}</div>${modelTable(p.id)}</section>`;}
function modelTable(provider){const rows=state.saved.models.filter(m=>m.provider===provider);return rows.length?`<table class="model-table"><colgroup><col style="width:35%"><col style="width:21%"><col class="limits-column" style="width:16%"><col class="bindings-column" style="width:18%"><col style="width:90px"></colgroup><thead><tr><th>模型</th><th>能力</th><th class="limits-column">上下文 / 输出</th><th class="bindings-column">正在使用</th><th style="text-align:right">操作</th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="model-name" data-act="edit-model" data-id="${m.id}">${e(m.name)} ${!m.enabled?'<span class="tag subtle">已停用</span>':''}${state.saved.defaultModel===m.id?'<span class="tag amber">默认</span>':''}</button><small>${e(m.apiModelId)}</small></td><td><span class="tag">${m.toolCall?'工具调用':'文本'}</span>${m.reasoning?' <span class="tag">推理</span>':''}</td><td class="limits-column numeric">${m.contextWindow.toLocaleString('en-US')} / ${m.maxTokens.toLocaleString('en-US')}</td><td class="bindings bindings-column">${e(refs(m.id).filter(x=>x!=='全局默认').join('、')||'未分配角色')}</td><td><div class="table-actions">${ib('star',state.saved.defaultModel===m.id?'已是全局默认':'设为全局默认','set-default',`data-id="${m.id}" ${state.saved.defaultModel===m.id||!usableModel(m.id)?'disabled':''}`)}${ib('edit','编辑模型','edit-model',`data-id="${m.id}"`)}${ib('trash','删除模型','delete-model',`data-id="${m.id}"`)}</div></td></tr>`).join('')}</tbody></table>`:`<div class="model-empty"><h3>为这个服务添加第一个模型</h3><p class="muted">填入服务商提供的模型标识，再分配给班班的不同角色。</p></div>`;}
function modelForm(){const m=modelDraft();return `<button class="text back-link" data-act="back-models">${icon('right')}返回供应商模型列表</button><div class="object-heading"><div><h2>${findModel(m.id)?e(m.name):'新增模型'}</h2><p>所属服务：${e(findProvider(m.provider)?.name)}</p></div><span class="tag subtle">参数为合成示例，非实测规格</span></div><div class="form-grid">${field('显示名称',input('model.name',m.name,'例如：团队主力','maxlength="100"'))}${field('API 模型标识',input('model.apiModelId',m.apiModelId,'服务商提供的deployment / model ID','maxlength="256"'))}${field('上下文窗口（tokens）',num('model.contextWindow',m.contextWindow,1024,2000000,1024))}${field('最大输出（tokens）',num('model.maxTokens',m.maxTokens,256,m.contextWindow,256))}${field('说明',input('model.description',m.description,'可选，方便后续挑选模型'),'',true)}</div><div class="switch-row"><div><strong>启用模型</strong><p>停用前需调整全局默认和角色分配。</p></div><input class="switch" type="checkbox" role="switch" aria-label="启用模型" data-bind="model.enabled" ${m.enabled?'checked':''}></div><div class="switch-row"><div><strong>工具调用</strong><p>允许角色调用已配置的Skills与MCP工具。</p></div><input class="switch" type="checkbox" role="switch" aria-label="工具调用" data-bind="model.toolCall" ${m.toolCall?'checked':''}></div><div class="switch-row"><div><strong>推理能力</strong><p>需模型及接口适配共同支持。</p></div><input class="switch" type="checkbox" role="switch" aria-label="推理能力" data-bind="model.reasoning" ${m.reasoning?'checked':''}></div>${m.reasoning?`<div class="field" style="margin-top:12px"><label for="control-reasoning">默认推理强度</label>${selectControl('reasoning',m.effort,[['default','由服务决定'],['off','关闭'],['low','较低'],['medium','标准'],['high','较高']])}</div>`:''}<details class="advanced"><summary>采样与显示选项${icon('down')}</summary><div class="form-grid">${field('Temperature（可选）',input('model.temperature',m.temperature,'留空使用服务默认','inputmode="decimal" data-min="0" data-max="2" data-float data-optional'))}${field('Top P（可选）',input('model.topP',m.topP,'留空使用服务默认','inputmode="decimal" data-min="0" data-max="1" data-float data-optional'))}${field('别名（可选）',input('model.aliases',m.aliases,'以逗号分隔，用于搜索'),'',true)}</div><p>推理及采样字段是拟接入项，确认后验证实际请求，不将保存视作已生效。</p></details><details class="advanced"><summary>成本记录（可选）${icon('down')}</summary><div class="form-grid">${field('计价货币',selectControl('currency',m.currency,[['CNY','人民币 CNY'],['USD','美元 USD']]))}${field('输入 / 每百万 tokens',input('model.priceInput',m.priceInput,'未填写','inputmode="decimal" data-min="0" data-max="1000000" data-float data-optional'))}${field('输出 / 每百万 tokens',input('model.priceOutput',m.priceOutput,'未填写','inputmode="decimal" data-min="0" data-max="1000000" data-float data-optional'))}${field('缓存读取 / 每百万 tokens',input('model.priceCache',m.priceCache,'未填写','inputmode="decimal" data-min="0" data-max="1000000" data-float data-optional'))}</div><p>仅保存本地记录，不代表实时价格；未填写保持未知。</p></details>`;}
function models(){return `<div class="provider-layout"><aside class="provider-rail" aria-label="供应商列表"><div class="rail-title"><span>供应商</span><span>${state.saved.providers.length}</span></div>${[...state.saved.providers,...(!findProvider(state.provider)?[providerDraft()]:[])].map(p=>`<button class="provider-item ${p.id===state.provider?'active':''}" data-act="provider" data-id="${p.id}"><span><strong>${e(p.name||'新供应商 · 未保存')}</strong><small>${state.saved.models.filter(m=>m.provider===p.id).length} 个模型 · ${p.enabled?'已启用':'已停用'}</small></span>${p.id===state.provider?icon('check'):''}</button>`).join('')}${btn(icon('plus')+'新增供应商','add-provider','quiet')}</aside><section class="provider-editor" aria-label="服务与模型编辑">${state.modelView?modelForm():providerForm()}</section></div>`;}
function agent(){const r=roles.find(r=>r.id===state.role),d=state.draft.roles[state.role];return `<div class="role-tabs" role="group" aria-label="内置智能体">${roles.map(role=>`<button class="role-tab ${role.id===state.role?'active':''}" aria-pressed="${role.id===state.role}" data-act="role" data-id="${role.id}">${icon(role.icon)}${role.name}</button>`).join('')}</div><div class="agent-workbench"><section class="agent-form"><div class="agent-intro"><div><h2>${r.name}</h2><p>${r.desc}</p></div><span class="tag subtle">内置 · 职责固定</span></div>${field('使用的模型',selectControl('role-model',d.modelId,modelOptions(true),'',true))}<div class="form-grid">${field('关注重点',selectControl('role-focus',d.focus,r.focus))}${field('表达详略',selectControl('role-detail',d.detail,[['concise','简洁'],['standard','标准'],['detailed','详细']]))}</div><div class="field"><span class="field-line"><label for="role-instructions">补充说明</label><small id="instruction-count">${d.instructions.length} / 4000</small></span><textarea id="role-instructions" data-bind="role.instructions" maxlength="4000" rows="5" placeholder="补充工作习惯，不替换角色职责。">${e(d.instructions)}</textarea></div><p class="rule-note">${icon('shield')}原文依据、人工签收与正式状态规则保持固定。</p><button class="text" data-act="reset-role" style="margin-top:14px">恢复当前角色默认</button></section><aside class="trial-pane" aria-label="隔离试跑"><div class="trial-heading"><h3>隔离试跑</h3><div class="mini-tabs"><button class="mini-tab ${state.trialTab==='sample'?'active':''}" data-act="trial-tab" data-id="sample">样例</button><button class="mini-tab ${state.trialTab==='result'?'active':''}" data-act="trial-tab" data-id="result">结果</button></div></div>${state.role!=='organizer'?`<div class="trial-unavailable"><h3>这个角色的试跑暂未开放</h3><p>模型和工作偏好可先配置。真实进展跟踪与今日建议留后续阶段。</p><span class="tag subtle">不影响保存配置</span></div>`:trialContent()}</aside></div>`;}
function shownTime(raw){if(!raw)return '未定期';const at=Date.parse(raw.replace(' ','T')+':00+08:00');return new Intl.DateTimeFormat('zh-CN',{timeZone:state.saved.general.zone,month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(at));}
function trialContent(){if(state.trialTab==='result'){if(state.trialStatus==='failed')return `<p class="inline-error">演示模型连接失败，原文与配置已保留。</p>${btn('回到样例','trial-sample','entry small')}`;if(state.trialStatus!=='passed')return '<p class="muted">先保存当前配置，再用样例查看只读预览。</p>';return `<p class="trial-status">演示结果 · 未新增正式事项</p><ul class="preview-list">${state.trialCandidates.map(c=>`<li><strong>${e(c.title)}</strong><p>${c.kind==='action'?'待我处理':'待我跟进'} · ${e(c.owner)} · ${shownTime(c.due)}</p><details><summary>原文依据</summary><blockquote>${e(c.evidence)}</blockquote></details></li>`).join('')}</ul><p class="muted" style="margin:9px 0 0">结果对应上一次已保存配置，不会随草稿变化。</p>`;}return `<p class="muted">用合成样例核对表达与字段。预览不进入待确认或正式事项，不执行工具。</p><div class="field"><label for="trial-text">试跑文本</label><textarea id="trial-text" data-bind="sample" rows="5" ${state.trialStatus==='running'?'disabled':''}>${e(state.sample)}</textarea></div><div class="trial-actions"><small>${dirty()?'先保存左侧配置。':state.trialStatus==='running'?'演示整理中…':'使用当前已保存配置。'}</small>${state.trialStatus==='running'?btn('取消','cancel-trial','quiet'):btn('开始试跑','start-trial','entry',dirty()?'disabled':'')}</div>`;}
function inbox(){return `<div class="page-heading"><div><h1>先过一眼，再交给班班盯。</h1><p>核对字段与原文，签收后才成为正式事项。</p></div></div><div class="inbox-commandbar">${field('来源批次',selectControl('batch',state.batch,[{value:'review',label:`接入评审纪要 · 待确认 ${state.candidates.filter(c=>c.status==='pending').length} 条`,description:'10月29日 · 3条候选'},{value:'mail',label:'需求沟通邮件 · 演示批次',description:'10月28日 · 查看已处理资料'}],'',true))}${btn(icon('plus')+'整理新文本','capture','entry')}</div><div class="inbox-grid"><section class="candidate-list" aria-label="候选事项">${state.candidates.map(c=>`<article class="candidate ${c.status==='accepted'?'signed':''}" aria-label="候选：${e(c.title)}"><div class="candidate-head">${c.status==='pending'?`<input type="checkbox" class="check" aria-label="选择${e(c.title)}" data-candidate-check="${c.id}" ${c.selected?'checked':''}>`:icon('check')}<strong>${e(c.title)}</strong><span class="tag ${c.status==='accepted'?'':'amber'}">${c.status==='accepted'?'已签收':'未签收'}</span></div><div class="candidate-metadata"><span>${c.kind==='action'?'待我处理':'待我跟进'}</span><span>${icon('user')}${e(c.owner)}</span><span>交付 ${shownTime(c.due)}</span>${c.followup?`<span>跟进 ${shownTime(c.followup)}</span>`:''}</div><blockquote>“${e(c.evidence)}”</blockquote><div class="candidate-footer"><span>有原文依据${c.status==='pending'?' · 待你确认':''}</span>${c.status==='pending'?`<div class="row-actions"><button class="text" data-act="edit-candidate" data-id="${c.id}">${state.editingCandidate===c.id?'收起编辑':'编辑字段'}</button><button class="text" data-act="discard-candidate" data-id="${c.id}">丢弃</button></div>`:''}</div>${state.editingCandidate===c.id?`<div class="form-grid">${field('事项标题',input(`candidate.${c.id}.title`,c.title),'',true)}${field('实际负责人',input(`candidate.${c.id}.owner`,c.owner))}${field('事项类型',selectControl(`candidate-kind-${c.id}`,c.kind,[['action','待我处理'],['followup','待我跟进']]))}${field('交付截止',dateControl(`candidate-due-${c.id}`,dateValue(`candidate-due-${c.id}`)))}${c.kind==='followup'?field('下次跟进',dateControl(`candidate-followup-${c.id}`,dateValue(`candidate-followup-${c.id}`))):''}</div>`:''}</article>`).join('')}</section><aside class="source-panel" aria-label="原文依据"><h2>原文依据</h2><div class="source-date">首次整理：${shownTime('2026-10-29 20:27')}</div>${state.candidates.map(c=>`<p>${e(c.evidence)}</p>`).join('')}</aside></div>`;}
function componentLab(){return `<section class="section-row"><div class="section-label"><h2>选择类</h2><p>统一搜索、分组、选中和弹层。</p></div><div class="section-body form-grid">${field('模型选择',selectControl('lab-model',state.saved.defaultModel,modelOptions(),'',true))}${field('禁用状态','<button class="control-select" disabled><span>当前不可选择</span>'+icon('down')+'</button>')}</div></section><section class="section-row"><div class="section-label"><h2>日期与时间</h2><p>中文面板，无浏览器原生日期弹层。</p></div><div class="section-body form-grid">${field('明确日期与时刻',dateControl('lab-date',state.labDate))}${field('仅日期',dateControl('lab-date-only',state.labDateOnly,true))}</div></section><section class="section-row"><div class="section-label"><h2>输入与校验</h2><p>标签、帮助与错误使用同一位置。</p></div><div class="section-body form-grid">${field('普通输入',input('lab-text','团队主力','输入名称'))}${field('数字步进',num('labNumber',state.labNumber,0,10))}${field('错误状态','<input class="input error-input" value="" aria-invalid="true" aria-describedby="lab-error"><small id="lab-error" class="error">请填写模型标识，草稿已保留。</small>')}${field('密码输入','<input class="input" type="password" value="demo-only" aria-label="演示密码输入" autocomplete="off">')}</div></section><section class="section-row"><div class="section-label"><h2>复选与开关</h2><p>多选用复选，启用状态用开关。</p></div><div class="section-body row-actions" style="gap:28px"><label class="toggle-line"><input type="checkbox" class="check" data-bind="labChecked" ${state.labChecked?'checked':''}>可选设置</label><label class="toggle-line"><input type="checkbox" class="switch" role="switch" data-bind="labSwitch" ${state.labSwitch?'checked':''}>启用服务</label></div></section><section class="section-row"><div class="section-label"><h2>操作层级</h2><p>入口浅琥珀，提交实心琥珀。</p></div><div class="section-body row-actions">${btn(icon('plus')+'入口操作','lab-entry','entry')}${btn('保存更改','lab-commit','commit')}${btn('次要操作','lab-quiet','secondary')}${btn('删除操作','lab-danger','danger')}</div></section>`;}
function about(){return `<img class="about-mark" src="../brand/sidekick-mark.svg" alt="班班"><h2>跟班 Sidekick</h2><p class="muted">盯着呢，老板。 / On it, boss.</p><div class="about-copy"><p>当前是待确认的布局评审原型，使用合成数据。不连接真实模型、飞书或MCP，不读取本机目录，也不改生产数据库。</p><p>已定品牌保持不变。模型参数与日期规则是设计提案，确认后才接入与验证。</p></div>`;}
function render(){closeSelect(false);closeDate(false);fieldSerial=0;menus={scene:{value:state.scene,search:false,items:[{value:'normal',label:'正常操作'},{value:'save-error',label:'保存失败'},{value:'connection-error',label:'连接失败'}]}};const settings=state.route!=='inbox';$('#navigation').innerHTML=`<button class="nav-button" data-act="today-info" aria-label="今日工作台">${icon('calendar')}<span>今日工作台</span></button><button class="nav-button ${state.route==='inbox'?'active':''}" data-route="inbox">${icon('inbox')}<span>待确认</span><b>${state.candidates.filter(c=>c.status==='pending').length}</b></button><button class="nav-button" data-act="all-info">${icon('list')}<span>全部事项</span></button>`;$('#profile-entry').classList.toggle('active',settings);$('#profile-entry').innerHTML=`<span class="avatar">${e(Array.from(state.saved.profile.name||'小明同学')[0])}</span><span><strong>${e(state.saved.profile.name||'小明同学')}</strong><small>个人信息与设置</small></span>`;$('#breadcrumb').innerHTML=`<div class="breadcrumb"><span>${settings?'设置':'事项'}</span>${icon('right')}<strong>${({general:'通用',profile:'个人信息',models:'模型服务',agents:'智能体',about:'关于',inbox:'待确认',components:'公共组件'})[state.route]}</strong></div>`;$('#view').innerHTML=state.route==='inbox'?inbox():`<div class="settings-body">${heading()}${state.route==='components'?'<div style="height:20px"></div>':tabs()}${({general,profile,models,agents:agent,about,components:componentLab})[state.route]()}</div>`;updateSavebar();document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function goto(route){closeDate(false);state.route=route;state.error='';history.replaceState(null,'',`#${route}`);render();$('#view').scrollTop=0;}
function notify(text,error=false){clearTimeout(toastTimer);const t=$('#toast');t.hidden=false;t.classList.toggle('error-toast',error);t.textContent=text;toastTimer=setTimeout(()=>t.hidden=true,4200);}
function getBinding(key){if(key.startsWith('profile.'))return state.draft.profile[key.slice(8)];if(key.startsWith('general.'))return state.draft.general[key.slice(8)];if(key.startsWith('provider.'))return providerDraft()[key.slice(9)];if(key.startsWith('model.'))return modelDraft()[key.slice(6)];if(key.startsWith('role.'))return state.draft.roles[state.role][key.slice(5)];return state[key];}
function setBinding(key,value){if(key.startsWith('candidate.')){const [,id,field]=key.split('.');state.candidates.find(c=>c.id===id)[field]=value;return;}if(key.startsWith('profile.'))state.draft.profile[key.slice(8)]=value;else if(key.startsWith('general.'))state.draft.general[key.slice(8)]=value;else if(key.startsWith('provider.'))providerDraft()[key.slice(9)]=value;else if(key.startsWith('model.'))modelDraft()[key.slice(6)]=value;else if(key.startsWith('role.'))state.draft.roles[state.role][key.slice(5)]=value;else if(key!=='lab-text')state[key]=value;state.error='';}
function clearFieldError(el){el.removeAttribute('aria-invalid');const ref=el.getAttribute('aria-describedby');if(ref?.startsWith('validation-')){$('#'+ref)?.remove();el.removeAttribute('aria-describedby');}}
function validateNumbers(){
 const fields=[...document.querySelectorAll('#view [data-min]')];let valid=true;
 for(const el of fields){clearFieldError(el);const v=el.value.trim(),n=Number(v);if(el.hasAttribute('data-optional')&&v==='')continue;if(v===''||!Number.isFinite(n)||(!el.hasAttribute('data-float')&&!Number.isInteger(n))||n<Number(el.dataset.min)||n>Number(el.dataset.max)){
  valid=false;const id=`validation-${el.dataset.bind.replaceAll('.','-')}`,note=document.createElement('small');note.id=id;note.className='error';note.textContent=`请输入 ${el.dataset.min}–${el.dataset.max} 范围内的${el.hasAttribute('data-float')?'数值':'整数'}。`;el.closest('.field').append(note);el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',id);
 }}
 if(!valid){state.error='有数值未填写或超出范围，请按字段提示修改。';updateSavebar();const first=fields.find(el=>el.hasAttribute('aria-invalid'));const details=first?.closest('details');if(details)details.open=true;first?.focus();}return valid;
}
function saveContext(){if(state.scene==='save-error'){state.error='演示保存失败，草稿已保留，可重试。';updateSavebar();return;}const c=context();if(!c)return;const d=clone(c.draft);if(keyDrafts[d.id])d.keyStored=true;delete d.keyChanged;if(!validateNumbers())return;if(state.route==='profile'){d.name=d.name.trim()||'小明同学';d.address=d.address.trim()||'BOSS';state.saved.profile=d;state.draft.profile=clone(d);}else if(state.route==='general')state.saved.general=clone(d);else if(state.route==='agents'){if(!usableModel(d.modelId||state.saved.defaultModel)){state.error='所选模型已停用或删除，请重新选择；草稿已保留。';updateSavebar();return;}state.saved.roles[state.role]=clone(d);}else if(state.route==='models'&&state.modelView){if(!d.enabled&&blocked(d.id))return;if(!d.name.trim()||!d.apiModelId.trim()){state.error='请填写模型名称和API标识。';updateSavebar();return;}if(Number(d.maxTokens)>Number(d.contextWindow)){state.error='最大输出不能超过上下文窗口。';updateSavebar();return;}const index=state.saved.models.findIndex(m=>m.id===d.id);if(index>=0)state.saved.models[index]=d;else state.saved.models.push(d);}else if(state.route==='models'){if(!d.enabled&&blocked(d.id,true))return;if(!d.name.trim()||!/^https?:\/\//.test(d.url)){state.error='请填写服务名称和有效服务地址。';updateSavebar();return;}if(/https?:\/\/[^/]*@|[?&](api[-_]?key|token|password)=/i.test(d.url)||/authorization|api[-_]?key|cookie|token/i.test(d.headerName)){state.error='认证信息请使用凭据引用，不要写入URL或附加请求头。';updateSavebar();return;}const secret=$('[data-key-draft]');if(secret?.value){d.keyStored=true;secret.value='';}const index=state.saved.providers.findIndex(p=>p.id===d.id);if(index>=0)state.saved.providers[index]=d;else state.saved.providers.push(d);state.draft.providers[d.id]=clone(d);delete keyDrafts[d.id];}state.status[c.key]='更改已保存在当前原型页面。';state.error='';render();notify('演示保存完成；未修改真实配置。');}
function discard(){const c=context();if(!c)return;if(state.route==='models'&&!state.modelView)delete keyDrafts[state.provider];if(state.route==='profile')state.draft.profile=clone(state.saved.profile);else if(state.route==='general')state.draft.general=clone(state.saved.general);else if(state.route==='agents')state.draft.roles[state.role]=clone(state.saved.roles[state.role]);else if(state.route==='models'&&state.modelView){if(!findModel(state.model)){state.modelView=false;state.model=null;}else state.draft.models[state.model]=clone(findModel(state.model));}else if(state.route==='models'){if(!findProvider(state.provider))state.provider=state.saved.providers[0]?.id;else state.draft.providers[state.provider]=clone(findProvider(state.provider));}state.error='';render();}
