document.addEventListener('input',event=>{const el=event.target;if(el.id==='select-search'&&activeMenu){drawOptions(el.value);return;}if(el.hasAttribute('data-key-draft')){if(el.value){keyDrafts[state.provider]=el.value;providerDraft().keyChanged=true;}else{delete keyDrafts[state.provider];delete providerDraft().keyChanged;}state.error='';updateSavebar();return;}const key=el.dataset.bind;if(!key)return;let value=el.type==='checkbox'?el.checked:el.value;if(el.dataset.min!==undefined&&value!==''){const number=Number(value);if(Number.isFinite(number))value=number;if(Number.isFinite(number))el.setAttribute('aria-valuenow',number);else el.removeAttribute('aria-valuenow');clearFieldError(el);}if(value===false&&(key==='provider.enabled'||key==='model.enabled')){const id=key==='provider.enabled'?state.provider:state.model;if(blocked(id,key==='provider.enabled')){el.checked=true;return;}}setBinding(key,value);if(key==='model.contextWindow'){const out=$('[data-bind="model.maxTokens"]');if(out){out.dataset.max=value;out.setAttribute('aria-valuemax',value);}}if(key==='role.instructions')$('#instruction-count').textContent=`${String(value).length} / 4000`;updateSavebar();if(el.type==='checkbox'&&(key==='model.reasoning'||key==='model.toolCall'))render();});
