document.addEventListener('pointerdown',event=>{if(activeMenu&&!$('#select-popover').contains(event.target)&&!activeMenu.trigger.contains(event.target))closeSelect(false);if(dateState&&!$('#date-popover').contains(event.target)&&!dateState.trigger.contains(event.target)&&!$('#select-popover').contains(event.target))closeDate(false);});
