function fullTime(raw,zone=state.saved.general.zone){
 if(!raw)return '';
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(raw));
 const p=Object.fromEntries(parts.map(v=>[v.type,v.value]));return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`;
}
function zonedInstants(civil){
 const [year,month,day,hour,minute]=civil.match(/\d+/g).map(Number),base=Date.UTC(year,month-1,day,hour,minute),matches=[];
 for(let offset=-14*60;offset<=14*60;offset+=30){const at=base-offset*60000;if(fullTime(at)===civil)matches.push(at);}
 return matches;
}
function dateValue(name){
 if(name==='lab-date')return state.labDate;if(name==='lab-date-only')return state.labDateOnly;if(name==='source-time')return state.sourceTime;
 const match=name.match(/^candidate-(due|followup)-(.+)$/);if(match){const value=state.candidates.find(c=>c.id===match[2])[match[1]];return value?fullTime(value.replace(' ','T')+':00+08:00'):'';}return '';
}
function openDate(trigger,name,only){
 if(dateState?.name===name){closeDate();return;}closeSelect(false);closeDate(false);
 const value=dateValue(name),[date,time='09:00']=value.split(' '),chosen=date||'2026-10-29';
 trigger.setAttribute('aria-expanded','true');dateState={trigger,name,only,chosen,month:chosen.slice(0,7),time,ambiguity:null};
 const p=$('#date-popover');($('#dialog').open?$('#dialog'):document.body).append(p);p.hidden=false;drawDate();
 p.showPopover();positionOverlay(p,trigger,328,only?365:425);p.querySelector('[aria-selected=true]')?.focus();
}
function closeDate(focus=true){const old=dateState,p=$('#date-popover');if(p?.matches(':popover-open'))p.hidePopover();if(p)p.hidden=true;dateState=null;old?.trigger.setAttribute('aria-expanded','false');if(focus&&old?.trigger.isConnected)old.trigger.focus();}
function isoDay(at){return new Date(at).toISOString().slice(0,10);}
function drawDate(){
 if(!dateState)return;const d=dateState,[y,m]=d.month.split('-').map(Number),first=Date.UTC(y,m-1,1),start=first-((new Date(first).getUTCDay()+6)%7)*86400000;
 const focusDay=d.chosen.slice(0,7)===d.month?d.chosen:d.month+'-01';
 const cells=Array.from({length:42},(_,i)=>{const iso=isoDay(start+i*86400000),day=Number(iso.slice(-2)),outside=iso.slice(0,7)!==d.month;return `<button type="button" role="gridcell" tabindex="${iso===focusDay?'0':'-1'}" aria-label="${iso.replace('-','年').replace('-','月')}日" aria-selected="${iso===d.chosen}" data-day="${iso}" class="calendar-day ${outside?'outside':''} ${iso==='2026-10-29'?'today':''}">${day}</button>`;});
 $('#date-popover').innerHTML=`<header class="calendar-header"><button class="icon-btn previous" data-date-shift="-1" aria-label="上个月">${icon('right')}</button><strong>${y}年 ${m}月</strong><button class="icon-btn" data-date-shift="1" aria-label="下个月">${icon('right')}</button></header><div class="calendar-weekdays" aria-hidden="true">${['一','二','三','四','五','六','日'].map(w=>`<span>${w}</span>`).join('')}</div><div class="calendar-grid" role="grid" aria-label="${y}年${m}月">${Array.from({length:6},(_,i)=>`<div role="row">${cells.slice(i*7,i*7+7).join('')}</div>`).join('')}</div><div class="calendar-shortcuts"><button class="text" data-day="2026-10-29">今天</button><button class="text" data-day="2026-10-30">明天</button><span>已选 ${d.chosen.replaceAll('-','/')}</span></div>${d.only?'':`<div class="calendar-time"><span>时间</span><div class="time-parts"><label class="sr-only" for="picker-hour">小时</label><input id="picker-hour" inputmode="numeric" maxlength="2" role="spinbutton" aria-valuemin="0" aria-valuemax="23" aria-valuenow="${Number(d.time.slice(0,2))}" value="${d.time.slice(0,2)}"><span>:</span><label class="sr-only" for="picker-minute">分钟</label><input id="picker-minute" inputmode="numeric" maxlength="2" role="spinbutton" aria-valuemin="0" aria-valuemax="59" aria-valuenow="${Number(d.time.slice(3))}" value="${d.time.slice(3)}"></div><small>24小时制</small></div>`}<p class="date-error" id="date-error" role="status" hidden></p><div class="date-ambiguity" hidden><span>这个时刻出现两次</span>${btn('选择较早','date-earlier','entry small')}${btn('选择较晚','date-later','entry small')}</div><footer class="calendar-footer">${btn('清空','date-clear','quiet small')}<span></span>${btn('取消','date-cancel','quiet small')}${btn('确定','date-apply','commit small')}</footer>`;
}
function shiftDateMonth(delta){const d=dateState,[y,m]=d.month.split('-').map(Number);d.month=isoDay(Date.UTC(y,m-1+delta,1)).slice(0,7);drawDate();$(`#date-popover [data-date-shift="${delta}"]`)?.focus();}
function applyDate(clear=false,choice=null){
 const d=dateState;if(!d)return;
 let value=clear?'':d.chosen;
 if(!clear&&!d.only){
  const h=$('#picker-hour').value,min=$('#picker-minute').value;
  if(!/^\d{1,2}$/.test(h)||!/^\d{1,2}$/.test(min)||Number(h)>23||Number(min)>59){$('#date-error').hidden=false;$('#date-error').textContent='请输入有效的小时（0–23）和分钟（0–59）。';return;}
  value+=` ${h.padStart(2,'0')}:${min.padStart(2,'0')}`;
 }
 const match=d.name.match(/^candidate-(due|followup)-(.+)$/);
 if(match&&value){const instants=zonedInstants(value);if(!instants.length){$('#date-error').hidden=false;$('#date-error').textContent='这个时刻不存在，请重新选择。';return;}if(instants.length>1&&choice===null){d.ambiguity=instants;$('#date-popover .date-ambiguity').hidden=false;return;}value=fullTime(instants[choice==='later'?instants.length-1:0],'Asia/Shanghai');}
 const name=d.name;
 if(name==='lab-date')state.labDate=value;else if(name==='lab-date-only')state.labDateOnly=value;else if(name==='source-time')state.sourceTime=value;else if(match)state.candidates.find(c=>c.id===match[2])[match[1]]=value;
 closeDate(false);
 if(name==='source-time'){const target=$('[data-date=source-time]');target.querySelector('.selection').textContent=value||'选择日期与时间';target.querySelector('.selection').classList.toggle('muted',!value);target.focus();}else{render();$(`[data-date="${name}"]`)?.focus();}
}
Object.assign(actions,{'date-clear':()=>applyDate(true),'date-cancel':()=>closeDate(),'date-apply':()=>applyDate(),'date-earlier':()=>applyDate(false,'earlier'),'date-later':()=>applyDate(false,'later')});
document.addEventListener('click',event=>{
 const el=event.target.closest('button');if(!el||!dateState)return;
 if(el.dataset.day){dateState.chosen=el.dataset.day;dateState.month=el.dataset.day.slice(0,7);drawDate();$('#date-popover [aria-selected=true]')?.focus();}
 if(el.dataset.dateShift)shiftDateMonth(Number(el.dataset.dateShift));
});
document.addEventListener('input',event=>{if(dateState&&['picker-hour','picker-minute'].includes(event.target.id)){dateState.time=`${$('#picker-hour').value.padStart(2,'0')}:${$('#picker-minute').value.padStart(2,'0')}`;event.target.setAttribute('aria-valuenow',Number(event.target.value));$('#date-error').hidden=true;$('#date-popover .date-ambiguity').hidden=true;}});
document.addEventListener('keydown',event=>{
 const day=event.target.closest('[role=gridcell]');
 if(day&&dateState&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(event.key)){
  event.preventDefault();const at=Date.parse(day.dataset.day+'T12:00:00Z'),weekday=(new Date(at).getUTCDay()+6)%7;
  const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7,Home:-weekday,End:6-weekday}[event.key];
  if(delta!==undefined){dateState.chosen=isoDay(at+delta*86400000);dateState.month=dateState.chosen.slice(0,7);}else{shiftDateMonth(event.key==='PageUp'?-1:1);dateState.chosen=dateState.month+'-01';}
  drawDate();$('#date-popover [aria-selected=true]')?.focus();return;
 }
 const el=event.target;if(!['ArrowUp','ArrowDown'].includes(event.key))return;
 if(el.matches('.number-control [data-min]')){event.preventDefault();const amount=Number(el.parentElement.querySelector('[data-delta]:last-child').dataset.delta),v=Math.min(Number(el.dataset.max),Math.max(Number(el.dataset.min),Number(el.value)+(event.key==='ArrowUp'?amount:-amount)));el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.setAttribute('aria-valuenow',v);}
 if(['picker-hour','picker-minute'].includes(el.id)){event.preventDefault();const max=el.id==='picker-hour'?23:59,v=(Number(el.value)+(event.key==='ArrowUp'?1:max))%(max+1);el.value=String(v).padStart(2,'0');el.dispatchEvent(new Event('input',{bubbles:true}));}
});
$('#dialog').addEventListener('cancel',event=>{if(activeMenu||dateState){event.preventDefault();closeSelect();closeDate();}});
render();
